package kigali.clinic.rw.controller;
import kigali.clinic.rw.domain.*; import kigali.clinic.rw.service.*; import kigali.clinic.rw.repository.*;
import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/appointments") public class AppointmentController {
 private final AppointmentService service; private final PrescriptionService prescriptions; private final AppointmentRepository repo;
 public AppointmentController(AppointmentService s,PrescriptionService p,AppointmentRepository r){service=s;prescriptions=p;repo=r;}
 @PostMapping("/save") public ResponseEntity<?> save(@RequestBody Appointment a){if(a.getAppointmentDate()!=null&&a.getAppointmentDate().isBefore(LocalDate.now()))return ResponseEntity.badRequest().body("Appointment date cannot be in the past");a.setStatus(AppointmentStatus.SCHEDULED);Object r=service.saveWithBookingCheck(a);if(r instanceof String)return ResponseEntity.status(409).body(r);return ResponseEntity.status(201).body(r);}
 @GetMapping public List<Appointment> all(){return service.findAll();}
 @GetMapping("/{id}") public ResponseEntity<?> one(@PathVariable Long id){return service.findById(id).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}
 @PutMapping("/update") public ResponseEntity<?> update(@RequestBody Appointment incoming){if(incoming.getId()==null||service.findById(incoming.getId()).isEmpty())return ResponseEntity.notFound().build();Appointment existing=service.findById(incoming.getId()).get();existing.setAppointmentDate(incoming.getAppointmentDate());existing.setNotes(incoming.getNotes());existing.setDoctor(incoming.getDoctor());existing.setPatient(incoming.getPatient());return ResponseEntity.ok(service.update(existing));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){if(service.findById(id).isEmpty())return ResponseEntity.notFound().build();if(prescriptions.hasForAppointment(id))return ResponseEntity.status(409).body("That appointment has prescriptions, delete them first");service.delete(id);return ResponseEntity.noContent().build();}
 @GetMapping("/by-status") public List<Appointment> byStatus(@RequestParam AppointmentStatus status){return service.byStatus(status);}
 @GetMapping("/between") public List<Appointment> between(@RequestParam String start,@RequestParam String end){return service.between(LocalDate.parse(start),LocalDate.parse(end));}
 @GetMapping("/stats/by-status") public List<Object[]> stats(){return service.statsByStatus();}
 @PatchMapping("/cancel-day") public String cancelDay(@RequestParam Long doctorId,@RequestParam String date){return service.cancelDoctorDay(doctorId,LocalDate.parse(date));}
 @GetMapping("/page") public Page<Appointment> page(@RequestParam int page,@RequestParam int size,@RequestParam String sort){String[] x=sort.split(",",2);Sort.Direction d=x.length>1&&x[1].equalsIgnoreCase("desc")?Sort.Direction.DESC:Sort.Direction.ASC;return service.page(PageRequest.of(page,size,Sort.by(d,x[0])));}
 @DeleteMapping("/cancelled-before") public String deleteCancelledBefore(@RequestParam String date){return service.deleteCancelledBefore(LocalDate.parse(date));}
 @PatchMapping("/{id}/status") public ResponseEntity<String> status(@PathVariable Long id,@RequestParam AppointmentStatus status){String m=service.changeStatus(id,status);if(m.equals("The appointment with that id does not exist"))return ResponseEntity.status(404).body(m);if(m.startsWith("Cannot change status"))return ResponseEntity.badRequest().body(m);return ResponseEntity.ok(m);}
 @PatchMapping("/{id}/reschedule") public ResponseEntity<String> reschedule(@PathVariable Long id,@RequestParam String newDate){String m=service.reschedule(id,LocalDate.parse(newDate));if(m.equals("The appointment with that id does not exist"))return ResponseEntity.status(404).body(m);if(m.startsWith("Doctor is already booked"))return ResponseEntity.status(409).body(m);if(m.equals("Appointment date cannot be in the past")||m.contains("cannot be rescheduled"))return ResponseEntity.badRequest().body(m);return ResponseEntity.ok(m);}
}
